WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.id_oi,a.ma_vt,a.ten_vt,a.dvt,a.sl_yc,a.sl_ton,a.sl_da_cap,a.sl_can_cap,a.sl_su_dung,a.sl_con_lai,a.sl_xac_nhan,a.sl_sau_can,a.sl_thu_hoi,a.sl_chenh_lech,a.sl_cbsx,a.sl_can_thu_hoi,a.sl_con_lai_dm,a.stt,a.update_yn,a.date0,a.time0,a.material_replace_code,count(*) OVER() total FROM public.mes_oi_material_history a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.date0 BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.id_oi ILIKE '%%'||s.search_key||'%%' OR a.ma_vt=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR EXISTS(SELECT 1 FROM public.mes_oi_confirm c WHERE c.id_oi=a.id_oi AND c.branch_code=ANY(string_to_array(s.bs,',')))) ORDER BY a.date0 DESC,a.time0 DESC,a.id_oi,a.stt LIMIT (SELECT lim FROM p);
